part of 'academy_english_advanced_models.dart';
abstract final class EnglishAdvancedA2UnitTwoMiddle {
  static const lessons=<EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:4,title:"A Bicycle Repair",titleArabic:"تصليح الدراجة",storyTitle:"A Bicycle Repair",storyTitleArabic:"تصليح الدراجة",paragraphs:<String>["On the way to class, Yusuf heard a strange noise from his bicycle. The front tire was flat, and the chain looked loose. He stopped beside a workshop and asked the mechanic for help.","The mechanic lifted the bicycle onto a stand and used a pump to fill the tire. She found a small hole near the valve and fixed it with a patch. Then she tightened the chain and tested the brakes.","Yusuf paid for the repair and rode slowly around the block. Everything worked again. He promised to check the wheels each weekend because a short inspection could prevent another problem."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bicycle","دراجة"),EnglishAdvancedWord("tire","إطار"),EnglishAdvancedWord("chain","سلسلة"),EnglishAdvancedWord("workshop","ورشة"),EnglishAdvancedWord("mechanic","ميكانيكي"),EnglishAdvancedWord("stand","حامل"),EnglishAdvancedWord("pump","مضخة"),EnglishAdvancedWord("valve","صمام"),EnglishAdvancedWord("patch","رقعة إصلاح"),EnglishAdvancedWord("tightened","شدّ"),EnglishAdvancedWord("brakes","مكابح"),EnglishAdvancedWord("wheels","عجلات")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("helmet strap","حزام خوذة"),EnglishAdvancedWord("wheel rim","حافة عجلة"),EnglishAdvancedWord("inner tube","أنبوب داخلي"),EnglishAdvancedWord("pedal","دواسة"),EnglishAdvancedWord("handlebar grip","مقبض المقود"),EnglishAdvancedWord("reflector","عاكس ضوء"),EnglishAdvancedWord("gear lever","ذراع الغيار"),EnglishAdvancedWord("lubricant","مادة تشحيم"),EnglishAdvancedWord("cycle lane","مسار دراجات"),EnglishAdvancedWord("bicycle lock","قفل دراجة"),EnglishAdvancedWord("spare tube","أنبوب احتياطي"),EnglishAdvancedWord("repair kit","عدة إصلاح")],grammarTitle:"Present perfect with just and yet",grammarArabic:"نستخدم have أو has مع التصريف الثالث للفعل الماضي الذي أثره مستمر الآن. just لما حدث للتو، already لما اكتمل، yet في السؤال والنفي.",grammarExamples:<String>["The mechanic has just checked the brakes.","I have already paid for the repair.","Have you fixed the tire yet?"],listening:"Welcome to City Cycle Repairs. We offer free basic safety checks on Saturday morning. A mechanic can check your brakes, lights, tires and chain. Larger repairs need a separate booking. Bring your bicycle before eleven if possible. If you need a new inner tube, the mechanic will tell you the price before starting the work.",listeningQuestion:"Which service is free?",listeningOptions:<String>["A basic safety check","A new bicycle","Every major repair"],listeningAnswer:0,readingQuestion:"What caused the tire problem?",readingOptions:<String>["A small hole near the valve","Missing pedals","A broken helmet"],readingAnswer:0,writingCue:"The mechanic used a ____ to fix the hole.",writingAnswer:"patch"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:5,title:"The Pet Adoption",titleArabic:"تبنّي حيوان أليف",storyTitle:"The Pet Adoption",storyTitleArabic:"تبنّي حيوان أليف",paragraphs:<String>["Layla went to an animal shelter because she wanted to adopt a cat. A friendly staff member introduced her to several animals. One quiet kitten followed Layla around the room.","Before choosing, Layla asked about feeding times, vaccinations, and the kitten's behavior. She signed an adoption form and prepared a safe place at home. The worker told her to be patient during the first week.","At home, the kitten hid behind a cushion and refused to play. Layla left some food nearby and waited quietly. After a few days, the kitten began to explore and trust her."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("animal shelter","مأوى حيوانات"),EnglishAdvancedWord("adopt","يتبنّى"),EnglishAdvancedWord("staff member","موظف"),EnglishAdvancedWord("kitten","هر صغير"),EnglishAdvancedWord("feeding times","مواعيد إطعام"),EnglishAdvancedWord("vaccinations","لقاحات"),EnglishAdvancedWord("behavior","سلوك"),EnglishAdvancedWord("adoption form","استمارة تبنٍ"),EnglishAdvancedWord("cushion","وسادة صغيرة"),EnglishAdvancedWord("patient","صبور"),EnglishAdvancedWord("explore","يستكشف"),EnglishAdvancedWord("trust","ثقة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("pet carrier","حقيبة نقل الحيوان"),EnglishAdvancedWord("litter tray","صندوق الرمل"),EnglishAdvancedWord("scratching post","عمود خدش"),EnglishAdvancedWord("pet grooming","العناية بفرو الحيوان"),EnglishAdvancedWord("cat food dish","طبق طعام القط"),EnglishAdvancedWord("grooming brush","فرشاة تمشيط"),EnglishAdvancedWord("veterinary visit","زيارة بيطرية"),EnglishAdvancedWord("microchip","شريحة تعريف"),EnglishAdvancedWord("pet insurance","تأمين الحيوان"),EnglishAdvancedWord("playful behavior","سلوك مرح"),EnglishAdvancedWord("socialization","تآلف اجتماعي"),EnglishAdvancedWord("pet bedding","فراش الحيوان")],grammarTitle:"Have to and don't have to",grammarArabic:"have to للواجب، don't have to لغياب الضرورة، وmustn't للمنع. لا تخلط بين عدم الوجوب والمنع.",grammarExamples:<String>["You have to give the kitten fresh water.","You don't have to buy expensive toys.","You mustn't leave a dangerous window open."],listening:"Thank you for visiting our animal shelter. Every pet has a different personality. Spend some time with the animal before choosing. New owners have to fill out an adoption form and attend a short care meeting. We also provide information about nearby veterinary clinics. If your new pet seems nervous, offer a quiet space and do not force it to play.",listeningQuestion:"What should an owner do when a pet is nervous?",listeningOptions:<String>["Give it a quiet space","Force it to play","Invite a noisy crowd"],listeningAnswer:0,readingQuestion:"How did Layla help the kitten?",readingOptions:<String>["She waited patiently","She moved it to another shelter","She shouted at it"],readingAnswer:0,writingCue:"Layla wanted to ____ a cat.",writingAnswer:"adopt"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:6,title:"An Invitation to Tea",titleArabic:"دعوة لشرب الشاي",storyTitle:"An Invitation to Tea",storyTitleArabic:"دعوة لشرب الشاي",paragraphs:<String>["Hana received a handwritten note from her neighbor inviting her to afternoon tea. Before leaving, she checked the address and chose a small box of dates as a present.","At the door, the host greeted her and introduced the other guests. They shared pastries and talked about favorite childhood memories. Hana listened carefully before joining the conversation.","When it was time to leave, Hana thanked the host for the hospitality. She offered to help clear the cups. On the way home, she decided to send a thank-you message the next morning."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("handwritten note","رسالة بخط اليد"),EnglishAdvancedWord("afternoon tea","شاي العصر"),EnglishAdvancedWord("address","عنوان"),EnglishAdvancedWord("dates","تمر"),EnglishAdvancedWord("present","هدية"),EnglishAdvancedWord("host","مضيف"),EnglishAdvancedWord("guests","ضيوف"),EnglishAdvancedWord("pastries","معجنات"),EnglishAdvancedWord("childhood memories","ذكريات الطفولة"),EnglishAdvancedWord("hospitality","ضيافة"),EnglishAdvancedWord("cups","أكواب"),EnglishAdvancedWord("thank-you message","رسالة شكر")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("tea tray","صينية شاي"),EnglishAdvancedWord("teapot","إبريق شاي"),EnglishAdvancedWord("sugar tongs","ملقط سكر"),EnglishAdvancedWord("serving plate","طبق تقديم"),EnglishAdvancedWord("guest etiquette","آداب الضيافة"),EnglishAdvancedWord("polite response","رد مهذب"),EnglishAdvancedWord("small talk","حديث اجتماعي"),EnglishAdvancedWord("conversation starter","فاتحة حديث"),EnglishAdvancedWord("arrival time","وقت الوصول"),EnglishAdvancedWord("farewell greeting","تحية وداع"),EnglishAdvancedWord("homemade biscuits","بسكويت منزلي"),EnglishAdvancedWord("social gathering","تجمع اجتماعي")],grammarTitle:"Would you like...?",grammarArabic:"Would you like + اسم أو to + فعل للدعوة المهذبة. ونستخدم Shall I لعرض المساعدة، وI'd love to لقبولها.",grammarExamples:<String>["Would you like some tea?","Would you like to join us on Friday?","Shall I help clear the table?"],listening:"Good afternoon, Hana. Thank you for accepting my invitation. Please come to number twelve Garden Lane on Friday at four thirty. You do not have to bring anything. We will have tea in the living room because the garden may be cold. If you cannot find the house, phone me when you reach the corner shop.",listeningQuestion:"Where will they have tea?",listeningOptions:<String>["In the living room","At the corner shop","In the garden"],listeningAnswer:0,readingQuestion:"What will Hana send the next morning?",readingOptions:<String>["A thank-you message","A railway timetable","A birthday invitation"],readingAnswer:0,writingCue:"Hana thanked the ____ before leaving.",writingAnswer:"host"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:7,title:"A Language Exchange",titleArabic:"تبادل اللغات",storyTitle:"A Language Exchange",storyTitleArabic:"تبادل اللغات",paragraphs:<String>["Every Wednesday, Ken and Fatima met at the community center to practise speaking. They wanted to use their skills rather than only reading textbooks. At first, both felt shy and often paused.","They set a timer and spent fifteen minutes in each language. Ken brought picture cards, while Fatima prepared a short role-play about ordering food. When they made mistakes, they gave each other kind feedback.","After several meetings, they spoke more fluently and enjoyed their recordings. They kept a notebook of useful expressions and studied them at home. They learned that regular practice was more helpful than being perfect."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("community center","مركز مجتمعي"),EnglishAdvancedWord("practise speaking","يتدرّب على التحدث"),EnglishAdvancedWord("textbooks","كتب دراسية"),EnglishAdvancedWord("shy","خجول"),EnglishAdvancedWord("paused","توقف"),EnglishAdvancedWord("timer","مؤقت"),EnglishAdvancedWord("picture cards","بطاقات صور"),EnglishAdvancedWord("role-play","تمثيل أدوار"),EnglishAdvancedWord("feedback","ملاحظات"),EnglishAdvancedWord("fluently","بطلاقة"),EnglishAdvancedWord("recordings","تسجيلات"),EnglishAdvancedWord("expressions","تعبيرات")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("pronunciation drill","تمرين نطق"),EnglishAdvancedWord("conversation prompt","موضوع محادثة"),EnglishAdvancedWord("conversation buddy","صديق محادثة"),EnglishAdvancedWord("word stress","نبر الكلمات"),EnglishAdvancedWord("listening log","سجل استماع"),EnglishAdvancedWord("speaking confidence","ثقة التحدث"),EnglishAdvancedWord("learning goal","هدف تعلم"),EnglishAdvancedWord("paired exercise","تدريب ثنائي"),EnglishAdvancedWord("correction strategy","طريقة تصحيح"),EnglishAdvancedWord("self-assessment","تقييم ذاتي"),EnglishAdvancedWord("flashcard review","مراجعة بطاقات"),EnglishAdvancedWord("weekly routine","روتين أسبوعي")],grammarTitle:"Present perfect with for and since",grammarArabic:"نستخدم المضارع التام مع for للمدة، وsince لنقطة البداية. مثال We have studied for two months وWe have studied since January.",grammarExamples:<String>["We have studied together for three weeks.","Ken has learned English since January.","How long have you known your partner?"],listening:"Welcome to the language exchange. First, practise a short conversation for twenty minutes. Then change roles and speak in your second language. Please do not interrupt every mistake; offer feedback after each conversation. You can use our picture cards or choose your own topic. Before leaving, write down two useful expressions and set one learning goal for next week.",listeningQuestion:"When should partners correct mistakes?",listeningOptions:<String>["After the conversation","After every word","Only at the end of the year"],listeningAnswer:0,readingQuestion:"Why did Ken and Fatima improve?",readingOptions:<String>["Regular practice and friendly feedback","Avoiding mistakes completely","Reading without speaking"],readingAnswer:0,writingCue:"They used a ____ to divide their practice time.",writingAnswer:"timer")
  ];
}
